########## src/components/marketing/navbar.tsx
import { NAV_LINKS } from "@/constants";
import { APP_URL } from "@/lib/zapi";
import { ArrowRightIcon } from "lucide-react";
import Link from "next/link";
import Icons from "../global/icons";
import Wrapper from "../global/wrapper";
import { Button } from "../ui/button";
import MobileMenu from "./mobile-menu";

const Navbar = ({
    signedIn = false,
    hasFaqs = false,
    registrationEnabled = true,
}: {
    signedIn?: boolean;
    hasFaqs?: boolean;
    registrationEnabled?: boolean;
}) => {
    const links = NAV_LINKS.filter((link) => hasFaqs || link.href !== "/#faq");
    const ctaHref = signedIn
        ? `${APP_URL}/portal/dashboard`
        : registrationEnabled
            ? `${APP_URL}/register`
            : `${APP_URL}/login`;
    const ctaLabel = signedIn
        ? "Ir al panel"
        : registrationEnabled
            ? "Empieza gratis"
            : "Iniciar sesión";

    return (
        <header className="sticky top-0 w-full h-16 bg-background/80 backdrop-blur-sm z-50">
            <Wrapper className="h-full">
                <div className="flex items-center justify-between h-full">
                    <div className="flex items-center">
                        <Link href="/" className="flex items-center gap-2">
                            <Icons.icon className="w-6" />
                            <span className="text-xl font-semibold hidden lg:block">
                                Zapi Social
                            </span>
                        </Link>
                    </div>

                    <div className="hidden lg:flex items-center gap-4">
                        <ul className="flex items-center gap-8">
                            {links.map((link, index) => (
                                <li key={index} className="text-sm font-medium -1 link">
                                    <Link href={link.href}>
                                        {link.name}
                                    </Link>
                                </li>
                            ))}
                        </ul>
                    </div>

                    <div className="flex items-center gap-4">
                        <Link href={ctaHref} className="hidden lg:block group">
                            <Button variant="blue">
                                {ctaLabel}
                                <ArrowRightIcon className="size-4 group-hover:translate-x-1 transition-all duration-300" />
