import Wrapper from "@/components/global/wrapper";
import Analysis from "@/components/marketing/analysis";
import Companies from "@/components/marketing/companies";
import CTA from "@/components/marketing/cta";
import FAQ from "@/components/marketing/faq";
import Features from "@/components/marketing/features";
import Hero from "@/components/marketing/hero";
import Integration from "@/components/marketing/integration";
import LanguageSupport from "@/components/marketing/lang-support";
import Pricing from "@/components/marketing/pricing";
import { PLAN } from "@/constants/plans";
import { APP_URL, getSite, hasSession, type SitePlan } from "@/lib/zapi";
import { headers } from "next/headers";

/**
 * Los planes salen del Admin. Un plan de Zapi es un registro por periodo, así
 * que mensual y anual se emparejan por nombre para alimentar el conmutador del
 * bloque de precios. Sin datos de la API se conserva el contenido por defecto
 * de la plantilla, de modo que la página nunca aparece vacía.
 */
function toPlans(
    plans: SitePlan[],
    registrationEnabled: boolean,
    signedIn: boolean,
): PLAN[] {
    const byName = new Map<string, { monthly?: SitePlan; yearly?: SitePlan }>();
    for (const plan of plans) {
        const entry = byName.get(plan.name) ?? {};
        entry[plan.billingType === "yearly" ? "yearly" : "monthly"] = plan;
        byName.set(plan.name, entry);
    }

    const result: PLAN[] = [];
    for (const [name, entry] of byName) {
        const base = entry.monthly ?? entry.yearly;
        if (!base) continue;
        const monthly = (entry.monthly ?? base).priceMinor / 100;
        const yearly = entry.yearly
            ? entry.yearly.priceMinor / 100
            : Math.round(monthly * 12 * 0.88);
        result.push({
            id: base.slug,
            title: name,
            desc: base.description,
            monthlyPrice: monthly,
            annuallyPrice: yearly,
            badge: base.featured ? "Más elegido" : undefined,
            buttonText: base.isFree ? "Empezar gratis" : `Elegir ${name}`,
            features: base.description
                .split(/\r?\n|·/)
                .map((line) => line.trim())
                .filter(Boolean),
            link: signedIn
                ? `${APP_URL}/portal/dashboard`
                : registrationEnabled
                  ? `${APP_URL}/register?plan=${base.slug}`
                  : `${APP_URL}/login`,
        });
    }
    return result.sort((a, b) => a.monthlyPrice - b.monthlyPrice);
}

const HomePage = async () => {
    const [site, signedIn] = await Promise.all([
        getSite(),
        hasSession((await headers()).get("cookie")),
    ]);
    const registrationEnabled = site?.settings.registrationEnabled ?? true;
    const plans = site?.plans.length
        ? toPlans(site.plans, registrationEnabled, signedIn)
        : undefined;

    return (
        <Wrapper className="py-20 relative">
            <Hero registrationEnabled={registrationEnabled} signedIn={signedIn} />
            <Companies />
            <Features />
            <Analysis />
            <Integration registrationEnabled={registrationEnabled} signedIn={signedIn} />
            <Pricing plans={plans} />
            <FAQ faqs={site?.faqs ?? []} />
            <LanguageSupport languages={site?.languages} />
            <CTA signedIn={signedIn} />
        </Wrapper>
    )
};

export default HomePage

