::-webkit-scrollbar {
  width: 4px;
}

::-webkit-scrollbar-thumb {
  background: hsl(var(--foreground)/0.1);
  border-radius: 10px;
}

::-webkit-scrollbar-track {
  background: hsl(var(--background));
}

img {
  user-select: none;
  pointer-events: none;
}

.link {
  position: relative;
  transition: color 0.3s ease-in-out;
}

.link::after {
  content: "";
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 0;
  height: 1px;
  background-color: hsl(var(--foreground));
  transition: width 0.3s ease-in-out;
  cursor: pointer;
  border-radius: 10px;
}

.link:hover::after {
  width: 100%;
}

.companies::before {
  content: "";
  position: absolute;
  top: 0%;
  left: 0;
  height: 1px;
  width: 100%;
  color: rgb(48, 48, 48);
  background: radial-gradient(50% 56400% at 50% 100%, rgb(34, 41, 57) 0%, rgba(169, 163, 194, 0) 100%);
}

.companies::after {
  content: "";
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  height: 20px;
  width: 70%;
  border-radius: 100%;
  filter: blur(6rem);
  background: rgb(85, 145, 243);
}

.footer::before {
  background: radial-gradient(50% 56400% at 50% 100%, rgb(34, 44, 57) 0%, rgba(169, 163, 194, 0) 100%);
  top: 0;
  content: "";
  height: 1px;
  left: 0;
  position: absolute;
  width: 100%;
  color: rgb(23, 23, 23);
}
