import type { PublicSiteFaq } from "@workspace/contracts"

import Container from "./container"

const FAQ = async ({ faqs }: { faqs: PublicSiteFaq[] }) => {
  if (!faqs.length) return null

  const t = await getTranslations("marketing.faq")

  return (
    <div
