                            <Link
                                key={post.slug}
                                href={`/blog/${post.slug}`}
                                className="flex flex-col rounded-2xl border border-foreground/10 bg-background/20 p-6 hover:border-foreground/20 transition-colors"
                            >
                                {post.categoryName ? (
                                    <span className="text-xs text-accent-foreground/60">
                                        {post.categoryName}
                                    </span>
                                ) : null}
                                <h2 className="text-lg font-medium mt-2">{post.title}</h2>
                                <p className="text-sm text-accent-foreground/80 mt-2 line-clamp-3">
                                    {post.excerpt}
                                </p>
                            </Link>
                        ))}
                    </div>
                ) : (
                    <p className="text-center text-accent-foreground/70">
                        Todavía no hay entradas publicadas.
                    </p>
                )}
            </Container>
        </Wrapper>
    )
};

export default BlogPage

