      });
  }

  private invalid() {
    return new AppException('VALIDATION_FAILED', HttpStatus.BAD_REQUEST);
  }

  private notFound() {
    return new AppException('PUBLIC_CONTENT_NOT_FOUND', HttpStatus.NOT_FOUND);
  }
}

