      "{count, plural, one {# idioma propio} other {# idiomas propios}}",
    overrideHint:
      "Solo afecta a este idioma. Si lo dejas sin personalizar, se usa el texto por defecto.",
  },
  en: {
    defaultCopy: "Default text",
    defaultCopyHint: "Used for every language without its own version.",
    localeLabel: "Version",
    overrideCount:
      "{count, plural, one {# custom language} other {# custom languages}}",
    overrideHint:
      "Only affects this language. Leave it uncustomised to use the default text.",
  },
}
function sortDeep(v) {
  if (Array.isArray(v)) return v.map(sortDeep)
  if (v === null || typeof v !== "object") return v
  return Object.fromEntries(Object.keys(v).sort().map((k) => [k, sortDeep(v[k])]))
}
for (const locale of ["es", "en"]) {
  const file = `packages/contracts/src/messages/${locale}.json`
  const c = JSON.parse(readFileSync(file, "utf8"))
  Object.assign(c.adminEmailTemplates, DATA[locale])
  delete c.adminEmailTemplates.localeTabs
  delete c.adminEmailTemplates.locale
  c.adminEmailTemplates = sortDeep(c.adminEmailTemplates)
  writeFileSync(file, JSON.stringify(c, null, 2) + "\n")
  console.log("ok", file)
}
