import pathlib
import re
import shutil

pages = pathlib.Path("pages")

for locale in ("es", "en"):
    (pages / locale).mkdir(exist_ok=True)

moved = 0
for src in sorted(pages.rglob("*")):
    if src.is_dir():
        continue
    parts = src.relative_to(pages).parts
    if parts[0] in ("es", "en"):
        continue
    match = re.match(r"^(.*)\.(es|en)\.(mdx|json)$", src.name)
    if not match:
        continue
    base, locale, ext = match.groups()
    dest_dir = pages / locale / src.parent.relative_to(pages)
    dest_dir.mkdir(parents=True, exist_ok=True)
    shutil.move(str(src), str(dest_dir / f"{base}.{ext}"))
    moved += 1

for folder in sorted(pages.rglob("*"), reverse=True):
    if folder.is_dir() and folder.name not in ("es", "en"):
        if not any(folder.iterdir()):
            folder.rmdir()

print(f"movidos {moved}")

